import{_ as a,c as t,o as l,b0 as o}from"./chunks/framework.Becqh7-x.js";const i="/linux-dev-docs/assets/20161126233946256.gC8CTTC1.png",r="/linux-dev-docs/assets/20161115012522086.eibXENff.png",d="/linux-dev-docs/assets/20161115012657365.BOIEvF1N.png",s="/linux-dev-docs/assets/20161115013021822.D4k41PWu.png",c="/linux-dev-docs/assets/20161115013138151.Byql-s6B.png",f=JSON.parse('{"title":"LV005-二维码简介","description":null,"frontmatter":{"title":"LV005-二维码简介","date":"2026-01-06T20:07:44.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/application/qrcode/126d2c6ee6a8167d3008c467","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-06T20:07:44.359Z","fulluuid":"d3008c467d894115a137b7767d7a74d3","useduuid":"d3008c467"}},"headers":[],"relativePath":"sdoc/application/qrcode/126d2c6ee6a8167d3008c467.md","filePath":"sdoc/20-应用开发/55-二维码识别/LV005-二维码简介.md","lastUpdated":1768604092000}'),n={name:"sdoc/application/qrcode/126d2c6ee6a8167d3008c467.md"};function p(u,e,_,h,m,R){return l(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="lv005-二维码简介" tabindex="-1">LV005-二维码简介 <a class="header-anchor" href="#lv005-二维码简介" aria-label="Permalink to &quot;LV005-二维码简介&quot;">​</a></h1><h2 id="一、二维码简介" tabindex="-1">一、二维码简介 <a class="header-anchor" href="#一、二维码简介" aria-label="Permalink to &quot;一、二维码简介&quot;">​</a></h2><h3 id="_1-什么是二维码" tabindex="-1">1. 什么是二维码 <a class="header-anchor" href="#_1-什么是二维码" aria-label="Permalink to &quot;1. 什么是二维码&quot;">​</a></h3><p>二维码（QR Code）是 1994 年由日本 DENSO WAVE 公司发明的矩阵式二维条码，QR 代表 &quot;Quick Response&quot;，具有信息容量大、可靠性高、可表示多种数据类型等特点。相比传统条形码，二维码在水平和垂直方向都可以存储信息，最大可容纳 7089 个数字或 4296 个字母。</p><img src="'+i+'" alt="这里写图片描述" style="zoom:67%;"><h3 id="_2-二维码的种类" tabindex="-1">2. 二维码的种类 <a class="header-anchor" href="#_2-二维码的种类" aria-label="Permalink to &quot;2. 二维码的种类&quot;">​</a></h3><p>在许多种类的二维条码中，常用的码制有：Data Matrix, Maxi Code, Aztec, QR Code, Vericode, PDF417, Ultracode, Code 49, Code 16K 等。</p><p>二维条码/二维码可以分为堆叠式/行排式二维条码和矩阵式二维条码。</p><ul><li>堆叠式/行排式二维条码，堆叠式/行排式二维条码又称堆积式二维条码或层排式二维条码，其编码原理是建立在一维条码基础之上，按需要堆积成二行或多行。它在编码设计、校验原理、识读方式等方面继承了一维条码的一些特点，识读设备与条码印刷与一维条码技术兼容。但由于行数的增加，需要对行进行判定，其译码算法与软件也不完全相同于一维条码。有代表性的行排式二维条码有：Code 16K、Code 49、PDF417、MicroPDF417 等。</li><li>矩阵式二维码，最流行莫过于 QR CODE , 我们常说的二维码就是它了。矩阵式二维条码（又称棋盘式二维条码）它是在一个矩形空间通过黑、白像素在矩阵中的不同分布进行编码。在矩阵相应元素位置上，用点（方点、圆点或其他形状）的出现表示二进制“1”，点的不出现表示二进制的“0”，点的排列组合确定了矩阵式二维条码所代表的意义。矩阵式二维条码是建立在计算机图像处理技术、组合编码原理等基础上的一种新型图形符号自动识读处理码制。具有代表性的矩阵式二维条码有：Code One、MaxiCode、QR Code、 Data Matrix、Han Xin Code、Grid Matrix 等。</li></ul><p>二维码在现实生活中的应用越来越普遍由于 QR CODE 的流行，<strong>二维码又称 QR code</strong>。</p><h3 id="_3-qr-码的特点" tabindex="-1">3. QR 码的特点 <a class="header-anchor" href="#_3-qr-码的特点" aria-label="Permalink to &quot;3. QR 码的特点&quot;">​</a></h3><ul><li>存储大容量信息：传统的条形码只能处理 20 位左右的信息量，与此相比，QR 码可处理条形码的几十倍到几百倍的信息量。另外，QR 码还可以支持所有类型的数据。（如：数字、英文字母、日文字母、汉字、符号、二进制、控制码等）。一个 QR 码最多可以处理 7089 字(仅用数字时)的巨大信息量。</li><li>在小空间内打印：QR 码使用纵向和横向两个方向处理数据，如果是相同的信息量，QR 码所占空间为条形码的十分之一左右。(还支持 Micro QR 码，可以在更小空间内处理数据)</li></ul><p><img src="'+r+'" alt="这里写图片描述"></p><ul><li>有效表现各种字母：QR 码是日本的二维码，因此非常适合处理日文字母和汉字。QR 码字集规格定义是按照日本标准“JIS 第一级和第二级的汉字”制定的，因此在日语处理方面，每一个全角字母和汉字都用 13 比特的数据处理，效率较高，与其他二维码相比，可以多存储 20%以上的信息。</li></ul><p><img src="'+d+'" alt="这里写图片描述"></p><ul><li><p>对变脏和破损的适应能力强：QR 码具备“纠错功能”，即使部分编码变脏或破损，也可以恢复数据。数据恢复以码字为单位（是组成内部数据的单位，在 QR 码的情况下，每 8 比特代表 1 码字），最多可以纠错约 30%（根据变脏和破损程度的不同，也存在无法恢复的情况）。</p></li><li><p>可以从任意方向读取：QR 码从 360° 任一方向均可快速读取。其奥秘就在于 QR 码中的 3 处定位图案，可以帮助 QR 码不受背景样式的影响，实现快速稳定的读取。</p></li></ul><p><img src="'+s+'" alt="这里写图片描述"></p><ul><li>支持数据合并功能：QR 码可以将数据分割为多个编码，最多支持 16 个 QR 码。使用这一功能，还可以在狭长区域内打印 QR 码。另外，也可以把多个分割编码合并为单个数据。</li></ul><p><img src="'+c+'" alt="这里写图片描述"></p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/u012611878/article/details/53167009" target="_blank" rel="noreferrer">二维码（QR code）基本结构及生成原理-CSDN 博客</a></p></blockquote>',20)])])}const g=a(n,[["render",p]]);export{f as __pageData,g as default};
